package com.xjtu.iron.idempotent.starter;import com.fasterxml.jackson.databind.ObjectMapper;import com.xjtu.iron.idempotent.api.spi.IdempotencyResultCodec;/** JSON 结果快照实现。 */public final class JacksonIdempotencyResultCodec implements IdempotencyResultCodec{private final ObjectMapper mapper;public JacksonIdempotencyResultCodec(ObjectMapper mapper){this.mapper=mapper;}public String encode(Object value)throws Exception{return mapper.writeValueAsString(value);}public<T>T decode(String payload,Class<T> type)throws Exception{return mapper.readValue(payload,type);}}
